"use client";

import { useEffect, useRef, useState } from "react";
import { ElevantApiError } from "@elevant/api-client";
import styles from "./AirlinePortalPage.module.css";

function problem(error: unknown) {
  if (error instanceof ElevantApiError && error.status === 403) return "Su cuenta no puede descargar este documento.";
  if (error instanceof ElevantApiError && error.status === 404) return "El documento ya no está disponible. Actualice la página.";
  return "No se pudo generar el PDF. Intente de nuevo.";
}

/**
 * «Descargar PDF» and «Imprimir» for a contract document generated by the API. Printing loads
 * the same PDF in a hidden frame and opens the browser's print dialog, so the paper copy is the
 * official layout (with the draft watermark when it applies), not the web page.
 */
export function ContractPdfActions({ load, fileName, label }: {
  load: () => Promise<Blob>;
  fileName: string;
  label: string;
}) {
  const [busy, setBusy] = useState<"" | "download" | "print">("");
  const [message, setMessage] = useState("");
  const frame = useRef<HTMLIFrameElement | null>(null);

  useEffect(() => () => { frame.current?.remove(); }, []);

  async function download() {
    setBusy("download"); setMessage("");
    try {
      const url = URL.createObjectURL(await load());
      const link = window.document.createElement("a");
      link.href = url; link.download = fileName; link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) { setMessage(problem(error)); }
    finally { setBusy(""); }
  }

  async function print() {
    setBusy("print"); setMessage("");
    try {
      const url = URL.createObjectURL(await load());
      frame.current?.remove();
      const iframe = window.document.createElement("iframe");
      iframe.title = `Impresión de ${label}`;
      iframe.setAttribute("aria-hidden", "true");
      iframe.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden";
      iframe.onload = () => {
        try { iframe.contentWindow?.focus(); iframe.contentWindow?.print(); }
        catch { window.open(url, "_blank", "noopener"); }
      };
      iframe.src = url;
      window.document.body.appendChild(iframe);
      frame.current = iframe;
    } catch (error) { setMessage(problem(error)); }
    finally { setBusy(""); }
  }

  return <div className={styles.pdfActions} role="group" aria-label={`Documento: ${label}`}>
    <button type="button" onClick={() => void download()} disabled={busy !== ""}>
      {busy === "download" ? "Generando PDF…" : "Descargar PDF"}</button>
    <button type="button" onClick={() => void print()} disabled={busy !== ""}>
      {busy === "print" ? "Preparando impresión…" : "Imprimir"}</button>
    {message && <p role="alert">{message}</p>}
  </div>;
}
